import type { Register } from 'claude-code'

const PANE = 'comandosmod'

const MODS = [
  { name: 'Comandos Mod', command: '/comandosmod', what: 'Esta lista: seus mods e como chamá-los.' },
  { name: 'Plain Answers', command: '/simples', what: 'Liga/desliga respostas em linguagem simples, sem jargão.' },
  { name: 'Session Dashboard', command: '/sessoes', what: 'Painel das sessões ativas: trabalhando, concluída ou esperando.' },
  { name: 'Assumption Session', command: '/suposicoes', what: 'Painel das suposições do Claude para você aprovar ou corrigir.' },
  { name: 'Prompt Enhance', command: '/melhorar', what: 'Melhora o prompt da caixa; depois clique em Enviar na faixa acima dela.' },
]

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'comandosmod', description: 'Lista todos os seus mods e o comando de cada um' })

    return next(e)
  })

  on('command.run', { command: 'comandosmod' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Meus mods' })

    return { text: 'Painel de mods aberto.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e) => {
    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        {MODS.map(m => (
          <Box key={m.command} flexDirection="column" marginBottom={1}>
            <Text bold>
              {m.name} {m.command}
            </Text>
            <Text dimColor>{m.what}</Text>
          </Box>
        ))}
      </Box>
    )
  })
}

